#define _GNU_SOURCE
#include <ctype.h>
#include <fcntl.h>
#include <stddef.h>
#include <string.h>
#include <unistd.h>

static int is_pid_exe_path(const char *path) {
  const char prefix[] = "/proc/";
  const char suffix[] = "/exe";
  const char *cursor;
  if (strncmp(path, prefix, sizeof(prefix) - 1) != 0) return 0;
  cursor = path + sizeof(prefix) - 1;
  if (!isdigit((unsigned char)*cursor)) return 0;
  while (isdigit((unsigned char)*cursor)) ++cursor;
  return strcmp(cursor, suffix) == 0;
}

ssize_t readlink(const char *restrict path, char *restrict buffer,
                 size_t buffer_size) {
  const char *resolved = is_pid_exe_path(path) ? "/proc/self/exe" : path;
  return readlinkat(AT_FDCWD, resolved, buffer, buffer_size);
}

