const r = await tools.exec_command({
  cmd: "python3 - <<'PY'
import json
from pathlib import Path
for p in [Path('/audit-input.json'), *Path('/reference/klean-generation').glob('*.json'), Path('/reference/klean-generation/generated/obligation-map.json'), Path('/reference/generation-tools/source-manifest.json'), Path('/opt/humaneval/data/klean-audit-tools.lock.json')]:
 d=json.loads(p.read_text())
 print(p)
 def walk(x,path=''):
  if isinstance(x,dict):
   for k,v in x.items():
    q=f'{path}.{k}' if path else k
    if 'sha256' in k.lower() or (isinstance(v,str) and v.startswith('sha256:')): print(q, '=', v)
    walk(v,q)
  elif isinstance(x,list):
   for i,v in enumerate(x): walk(v,f'{path}[{i}]')
 walk(d)
PY",
  workdir: "/audit-output",
  yield_time_ms: 10000,
  max_output_tokens: 40000
});
text(r.output);

